1	// The `claim-office` command: reads a JSON scenario from stdin and writes the
2	// JSON results to stdout.
3	import { text } from "node:stream/consumers";
4	import { runScenario, type Scenario } from "./claim-office.js";
5	
6	const main = async (): Promise<void> => {
7	  const scenario = JSON.parse(await text(process.stdin)) as Scenario;
8	  process.stdout.write(JSON.stringify(runScenario(scenario)));
9	};
10	
11	// A rejected scenario is reported as a description, not a crash: the message
12	// alone goes to stderr, nothing goes to stdout, and the exit code is non-zero.
13	try {
14	  await main();
15	} catch (error) {
16	  process.stderr.write(`${(error as Error).message}\n`);
17	  process.exitCode = 1;
18	}
19

1	import { describe, it, expect } from "vitest";
2	import { spawnSync } from "node:child_process";
3	import { runScenario } from "./claim-office.js";
4	
5	// Runs the real CLI as a subprocess so stdin, stdout, stderr and the exit code
6	// are all exercised as a user would see them.
7	const runCli = (
8	  input: unknown,
9	): { status: number | null; stdout: string; stderr: string } => {
10	  const result = spawnSync("npx", ["tsx", "src/cli.ts"], {
11	    input: JSON.stringify(input),
12	    encoding: "utf8",
13	  });
14	  return {
15	    status: result.status,
16	    stdout: result.stdout,
17	    stderr: result.stderr,
18	  };
19	};
20	
21	describe("MHPCO Claim Office", () => {
22	  // --- Quote: simplest case and single main items -------------------------
23	  it("empty item list → premium 5 G (only the processing fee)", () => {
24	    const result = runScenario({
25	      customer: { yearsWithMHPCO: 0 },
26	      steps: [{ op: "quote", items: [] }],
27	    });
28	
29	    expect(result).toEqual({ results: [{ premium: 5 }] });
30	  });
31	  it("plain sword (base 100 G) for a newcomer → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
32	    const result = runScenario({
33	      customer: { yearsWithMHPCO: 0 },
34	      steps: [
35	        {
36	          op: "quote",
37	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
38	        },
39	      ],
40	    });
41	
42	    expect(result).toEqual({ results: [{ premium: 115 }] });
43	  });
