48	        {
49	          op: "quote",
50	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
51	        },
52	      ],
53	    });
54	
55	    expect(result).toEqual({ results: [{ premium: 71 }] });
56	  });
57	  it("plain staff (base 80 G) for a newcomer → premium 93 G (80 + 8 first insurance + 5 fee)", () => {
58	    const result = runScenario({
59	      customer: { yearsWithMHPCO: 0 },
60	      steps: [
61	        {
62	          op: "quote",
63	          items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }],
64	        },
65	      ],
66	    });
67	
68	    expect(result).toEqual({ results: [{ premium: 93 }] });
69	  });
70	  it("plain potion (base 40 G) for a newcomer → premium 49 G (40 + 4 first insurance + 5 fee)", () => {
71	    const result = runScenario({
72	      customer: { yearsWithMHPCO: 0 },
73	      steps: [
74	        {
75	          op: "quote",
76	          items: [{ type: "potion", material: "glass", enchantment: 0, cursed: false }],
77	        },
78	      ],
79	    });
80	
81	    expect(result).toEqual({ results: [{ premium: 49 }] });
82	  });
83	
84	  // --- Components and blocks of 3 alike -----------------------------------
85	  it("1 rune → 25 G base premium", () => {
86	    const result = runScenario({
87	      customer: { yearsWithMHPCO: 0 },
88	      steps: [{ op: "quote", items: [{ type: "rune" }] }],
89	    });
90	
91	    // 25 base + 2.5 first insurance + 5 fee = 32.5 → 33 (rounded up)
92	    expect(result).toEqual({ results: [{ premium: 33 }] });
93	  });
94	  it("2 runes → 50 G base premium", () => {
95	    const result = runScenario({
96	      customer: { yearsWithMHPCO: 0 },
97	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
98	    });
99	
100	    // 50 base + 5 first insurance + 5 fee = 60
101	    expect(result).toEqual({ results: [{ premium: 60 }] });
102	  });
103	  it("3 runes → 60 G base premium (block applies)", () => {
104	    const result = runScenario({
105	      customer: { yearsWithMHPCO: 0 },
106	      steps: [
107	        {
108	          op: "quote",
109	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
110	        },
111	      ],
112	    });
113	
114	    // 60 block base (not 75) + 6 first insurance + 5 fee = 71
115	    expect(result).toEqual({ results: [{ premium: 71 }] });
116	  });
117	  it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
118	    const result = runScenario({
119	      customer: { yearsWithMHPCO: 0 },
120	      steps: [
121	        {
122	          op: "quote",
123	          items: [
124	            { type: "rune" },
125	            { type: "rune" },
126	            { type: "rune" },
127	            { type: "rune" },
128	          ],
129	        },
130	      ],
131	    });
132	
133	    // 100 base (no block) + 10 first insurance + 5 fee = 115
134	    expect(result).toEqual({ results: [{ premium: 115 }] });
135	  });
136	  it("7 runes → 175 G base premium", () => {
137	    const result = runScenario({
138	      customer: { yearsWithMHPCO: 0 },
139	      steps: [
140	        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
141	      ],
142	    });
143	
144	    // 175 base (7 x 25 — no block discount for subsets of a larger group)
145	    // + 17.5 first insurance + 5 fee = 197.5 → 198 (rounded up)
146	    expect(result).toEqual({ results: [{ premium: 198 }] });
147	  });
148	  it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
149	    const result = runScenario({
150	      customer: { yearsWithMHPCO: 0 },
151	      steps: [
152	        {
153	          op: "quote",
154	          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
155	        },
156	      ],
157	    });
158	
159	    // "alike" means the same type: 2 runes + 1 moonstone is not a block.
160	    // 75 base + 7.5 first insurance + 5 fee = 87.5 → 88 (rounded up)
161	    expect(result).toEqual({ results: [{ premium: 88 }] });
162	  });
163	  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
164	    const result = runScenario({
165	      customer: { yearsWithMHPCO: 0 },
166	      steps: [
167	        {
168	          op: "quote",
169	          items: [
170	            { type: "rune" },
171	            { type: "rune" },
172	            { type: "rune" },
173	            { type: "moonstone" },
174	            { type: "moonstone" },
