181	    // Two blocks of 3 alike components: 60 + 60 = 120 base
182	    // + 12 first insurance + 5 fee = 137
183	    expect(result).toEqual({ results: [{ premium: 137 }] });
184	  });
185	
186	  // --- Item-specific modifiers --------------------------------------------
187	  it("cursed sword adds a 50 % surcharge on that item's base premium (100 → 150)", () => {
188	    const result = runScenario({
189	      customer: { yearsWithMHPCO: 0 },
190	      steps: [
191	        {
192	          op: "quote",
193	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: true }],
194	        },
195	      ],
196	    });
197	
198	    // 100 base + 50 curse + 10 first insurance = 160 + 5 fee = 165
199	    expect(result).toEqual({ results: [{ premium: 165 }] });
200	  });
201	  it("sword with exactly enchantment 5 → high-enchantment surcharge applies (100 → 130)", () => {
202	    const result = runScenario({
203	      customer: { yearsWithMHPCO: 0 },
204	      steps: [
205	        {
206	          op: "quote",
207	          items: [{ type: "sword", material: "steel", enchantment: 5, cursed: false }],
208	        },
209	      ],
210	    });
211	
212	    // 100 base + 30 high enchantment + 10 first insurance + 5 fee = 145
213	    expect(result).toEqual({ results: [{ premium: 145 }] });
214	  });
215	  it("sword with enchantment 4 → no high-enchantment surcharge (100 → 100)", () => {
216	    const result = runScenario({
217	      customer: { yearsWithMHPCO: 0 },
218	      steps: [
219	        {
220	          op: "quote",
221	          items: [{ type: "sword", material: "steel", enchantment: 4, cursed: false }],
222	        },
223	      ],
224	    });
225	
226	    // 100 base + 10 first insurance + 5 fee = 115 (no surcharge below level 5)
227	    expect(result).toEqual({ results: [{ premium: 115 }] });
228	  });
229	  it("cursed sword with exactly enchantment 5 → both surcharges apply (100 → 180)", () => {
230	    const result = runScenario({
231	      customer: { yearsWithMHPCO: 0 },
232	      steps: [
233	        {
234	          op: "quote",
235	          items: [{ type: "sword", material: "steel", enchantment: 5, cursed: true }],
236	        },
237	      ],
238	    });
239	
240	    // Rates add, not compound: 100 base + 50 curse + 30 high enchantment
241	    // + 10 first insurance + 5 fee = 195
242	    expect(result).toEqual({ results: [{ premium: 195 }] });
243	  });
244	
245	  // --- Policy-wide modifiers ----------------------------------------------
246	  it("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies", () => {
247	    const result = runScenario({
248	      customer: { yearsWithMHPCO: 2 },
249	      steps: [
250	        {
251	          op: "quote",
